{"CommandLine":"$bytes = [System.IO.File]::ReadAllBytes("C:\Program Files\Allen & Heath\SQ MixPad 1.6.1\SQ MixPad.exe")
$text = [System.Text.Encoding]::ASCII.GetString($bytes)
foreach ($kw in @("Scene.cpp", "Show.cpp", "NVData", "sNVScene", "sNVShow", "sNVChannel", "CalcShowCRC", "TestSentinel")) {
    $idx = 0
    Write-Host "=== $kw ==="
    while (($idx = $text.IndexOf($kw, $idx)) -ge 0) {
        $start = [Math]::Max(0, $idx - 150)
        $len = [Math]::Min(500, $text.Length - $start)
        $sub = $text.Substring($start, $len) -replace "[^\x20-\x7E]+", " | "
        Write-Host "At $idx : $sub"
        $idx += $kw.Length
    }
}","WaitMsBeforeAsync":5000,"toolSummary":"Inspect Scene.cpp, Show.cpp, and NVData structures in SQ MixPad.exe"}
